* { box-sizing: border-box; }

:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #183c3a;
  background: #d9e8d7;
}

body {
  min-height: 100vh;
  margin: 0;
  padding: 24px 16px;
  display: grid;
  place-items: center;
  background-color: #d9e8d7;
  background-image: radial-gradient(#b8d1b4 1.5px, transparent 1.5px);
  background-size: 22px 22px;
}

.game-card {
  width: min(100%, 600px);
  padding: clamp(20px, 5vw, 36px);
  border: 4px solid #183c3a;
  border-radius: 10px;
  background: #fff9e9;
  box-shadow: 8px 8px 0 #183c3a;
  text-align: center;
}

.intro { margin-bottom: 24px; }
.eyebrow { margin: 0 0 8px; color: #ae563f; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; font-size: .8rem; }
h1 { margin: 0; font-size: clamp(1.8rem, 7vw, 2.7rem); line-height: 1.1; }
h1 span { color: #ae563f; }
.intro > p:last-child { margin: 12px 0 0; color: #46635a; }

.board-wrap { width: 100%; max-width: 500px; margin: 0 auto; padding: 6px; border: 3px solid #183c3a; background: #183c3a; }
.board {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  aspect-ratio: 1;
  gap: 3px;
  background: #183c3a;
}
.cell {
  position: relative;
  min-width: 0;
  display: flex;
  align-items: flex-start;
  justify-content: flex-start;
  padding: 5px;
  overflow: hidden;
  background: #e9c978;
  color: #183c3a;
  font-size: clamp(.68rem, 2.5vw, .9rem);
  font-weight: 800;
}
.cell:nth-child(4n), .cell:nth-child(4n + 1) { background: #f4dfa5; }
.cell.start, .cell.finish { background: #c5d9b3; }
.cell.finish { box-shadow: inset 0 0 0 3px #ae563f; }
.cell .mark { position: absolute; right: 4px; bottom: 3px; font-size: clamp(.75rem, 3vw, 1.1rem); line-height: 1; }
.cell.ladder .mark { color: #466d4d; }
.cell.snake .mark { color: #ae563f; }
.token {
  position: absolute;
  left: 50%; top: 57%;
  width: 28%; height: 28%;
  transform: translate(-50%, -50%);
  border: 3px solid #183c3a;
  background: #ae563f;
  box-shadow: 3px 3px 0 #183c3a;
  image-rendering: pixelated;
}
.token::before { content: ""; position: absolute; left: 25%; top: 22%; width: 3px; height: 3px; background: #fff9e9; box-shadow: 6px 0 #fff9e9; }

.game-controls { display: grid; grid-template-columns: 1fr 1.5fr; align-items: center; gap: 12px 16px; margin: 24px auto 0; max-width: 420px; }
.status { display: flex; align-items: center; gap: 10px; text-align: left; }
.status-label { color: #46635a; font-weight: 650; }
.status strong { display: grid; place-items: center; width: 42px; height: 42px; border: 3px solid #183c3a; background: #e9c978; font-size: 1.25rem; }
button { min-height: 50px; border: 3px solid #183c3a; border-radius: 4px; padding: 10px 16px; background: #ae563f; color: #fff9e9; font: inherit; font-weight: 800; cursor: pointer; box-shadow: 4px 4px 0 #183c3a; transition: transform .12s ease, box-shadow .12s ease, background .12s ease; }
button:hover { background: #914431; }
button:focus-visible { outline: 4px solid #e9c978; outline-offset: 4px; }
button:active { transform: translate(3px, 3px); box-shadow: 1px 1px 0 #183c3a; }
button:disabled { cursor: default; opacity: .7; }
.help { grid-column: 1 / -1; margin: 0; color: #46635a; font-size: .9rem; }
.message { grid-column: 1 / -1; min-height: 1.5em; margin: 0; color: #ae563f; font-weight: 800; }
footer { margin-top: 18px; color: #46635a; font-size: .9rem; }

@media (max-width: 420px) {
  body { padding: 14px 10px; }
  .game-card { padding: 18px 14px; box-shadow: 5px 5px 0 #183c3a; }
  .cell { padding: 3px; }
  .game-controls { gap: 12px 8px; }
  .status { gap: 6px; }
  .status-label { font-size: .92rem; }
  button { padding-inline: 8px; }
}

@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition-duration: .01ms !important; } }

const ladders = new Map([[3, 11], [8, 17], [20, 29]]);
const snakes = new Map([[14, 5], [24, 13], [28, 19]]);
const board = document.querySelector('#board');
const squareDisplay = document.querySelector('#square-display');
const message = document.querySelector('#message');
const rollButton = document.querySelector('#roll-button');
let position = 1;

const cells = new Map();
for (let row = 4; row >= 0; row--) {
  const rowStart = row * 6 + 1;
  const numbers = row % 2 === 0
    ? Array.from({ length: 6 }, (_, i) => rowStart + i)
    : Array.from({ length: 6 }, (_, i) => rowStart + 5 - i);
  for (const number of numbers) {
    const cell = document.createElement('div');
    cell.className = 'cell';
    cell.dataset.square = String(number);
    cell.setAttribute('aria-hidden', 'true');
    const label = document.createElement('span');
    label.textContent = String(number);
    cell.append(label);
    if (ladders.has(number)) {
      cell.classList.add('ladder');
      const mark = document.createElement('span');
      mark.className = 'mark';
      mark.textContent = '↗';
      cell.append(mark);
    } else if (snakes.has(number)) {
      cell.classList.add('snake');
      const mark = document.createElement('span');
      mark.className = 'mark';
      mark.textContent = '↘';
      cell.append(mark);
    }
    if (number === 1) cell.classList.add('start');
    if (number === 30) cell.classList.add('finish');
    board.append(cell);
    cells.set(number, cell);
  }
}

const token = document.createElement('span');
token.className = 'token';
token.setAttribute('aria-hidden', 'true');
function renderPosition() {
  for (const cell of cells.values()) cell.querySelector('.token')?.remove();
  cells.get(position).append(token);
  squareDisplay.textContent = String(position);
}

rollButton.addEventListener('click', () => {
  if (position === 30) return;
  const roll = Math.floor(Math.random() * 6) + 1;
  const next = position + roll;
  if (next > 30) {
    message.textContent = `You rolled ${roll}. Roll exactly to reach 30!`;
    return;
  }

  position = next;
  let result = `You rolled ${roll}.`;
  if (ladders.has(position)) {
    const destination = ladders.get(position);
    result += ` Ladder! Climb to ${destination}.`;
    position = destination;
  } else if (snakes.has(position)) {
    const destination = snakes.get(position);
    result += ` Snake! Slide to ${destination}.`;
    position = destination;
  }
  renderPosition();
  if (position === 30) {
    message.textContent = `${result} You win!`;
    rollButton.disabled = true;
    rollButton.textContent = 'You won!';
  } else {
    message.textContent = `${result} You are on square ${position}.`;
  }
});

renderPosition();
